import json
from parser import parse_header

malformed = 'Content-Length 42'
wellformed = 'Content-Length: 42'

try:
    parse_header(malformed)
except Exception as exc:
    exception = {"type": type(exc).__name__, "message": str(exc)}
    malformed_result = {"input": malformed, "raised": exception}
else:
    exception = {"type": None, "message": None}
    malformed_result = {"input": malformed, "returned": None}

try:
    returned = parse_header(wellformed)
    wellformed_result = {"input": wellformed, "returned": list(returned)}
except Exception as exc:
    wellformed_result = {"input": wellformed, "raised": {"type": type(exc).__name__, "message": str(exc)}}

