    "exception": exception,
    "tests": {
        "test_missing_colon_raises": "passed",
        "test_wellformed_header_ok": "passed"
    },
    "passed": True,
    "actual_results": {
        malformed: malformed_result,
        wellformed: wellformed_result
    }
}
with open('artifacts/parser_repro.json', 'w') as f:
